package lk.vezel.console;

/** Positions match the engraved faces generated by tools/prepare_instruments.py. */
final class GaugeScale {
    static final int MAX = 180, START = 138, SWEEP = 264;

    static float progress(int speed) { return Math.max(0f, Math.min(1f, speed / (float) MAX)); }
    static float angle(int speed) { return START + SWEEP * progress(speed); }
}
